package main

import (
	"fmt"
	"os"
	"strings"
)

// item-mod-stat-order-emit turns `gamedatadump item-mod-stat-order`'s dump into
// data/raw/item_mod_stat_order.go.
//
// ⚠️ THIS EMITTER HAS NO PYTHON ORIGINAL AND IS NOT A PORT, like mod-scalability-emit: the fold
// finished before this table existed, so its refusals carry //go-only markers.
//
// ⚠️ THE HEADER TEXT IS THE PRODUCT. `task data-regen -- --check` compares bytes.

const imsoHeader = `package raw

// CODE GENERATED BY ` + "`gamedatadump item-mod-stat-order`" + ` + ` + "`gopob item-mod-stat-order-emit`" + ` FROM %s. DO NOT EDIT.
// Regenerate with ` + "`task data-regen -- --only item-mod-stat-order`" + `.

// ItemModStatOrderEntry is one key of PoB's file-local ` + "`uniqueModStatOrder`" + `
// (src/Classes/Item.lua:1336-1347), which is TWO maps -- ` + "`exact`" + ` and ` + "`normalised`" + ` -- folded
// here into one so the table is a single chunkable literal. A key present in only one of them has
// 0 in the other field; the dumper refuses any statOrder <= 0, so 0 always means ABSENT.
//
// ⚠️ THE KEYS ARE BUILT BY UPSTREAM'S OWN CODE. Exact is ` + "`line:lower():gsub(\"\\n\", \" \")`" + ` and
// Normalised is normaliseModLine (:64-68), both run in the dumper over
// data.itemMods.ItemExclusive. A lookup must build its key the same way, byte for byte -- Lua's
// lower() is ASCII-only.
//
// ⚠️ THE VALUE IS THE MINIMUM statOrder OVER EVERY MOD SHARING THE KEY, and it is a float: some
// statOrders are fractional (390.1).
type ItemModStatOrderEntry struct {
	Exact      float64
	Normalised float64
}
`

// imsoDecoder is emitted with the table. The rows are an array of constants rather than a map literal: as code the
// 9982 keys were megabytes of the wasm module's package init; as an array they are data the linker lays out, put into
// the map by one loop.
const imsoDecoder = `
var ItemModStatOrder = decodeItemModStatOrder(itemModStatOrderRows[:])

type itemModStatOrderRow struct {
	key               string
	exact, normalised float64
}

func decodeItemModStatOrder(rows []itemModStatOrderRow) map[string]ItemModStatOrderEntry {
	m := make(map[string]ItemModStatOrderEntry, len(rows))
	for _, r := range rows {
		m[r.key] = ItemModStatOrderEntry{Exact: r.exact, Normalised: r.normalised}
	}
	return m
}
`

func itemModStatOrderEmit(argv []string) int {
	//go-only: no python original — the usage line names the SUBCOMMAND.
	if len(argv) != 2 {
		return oeUsage("usage: gopob item-mod-stat-order-emit <dump.json> <out.go>")
	}
	dump, rc := oeLoadDump(argv[0])
	if rc != 0 {
		return rc
	}
	exact := oeObject(dump["exact"])
	normalised := oeObject(dump["normalised"])

	// ⚠️ AN EMPTY TABLE IS INVISIBLE DOWNSTREAM: every line gets a nil order, and a stable sort on
	// an all-nil key is the identity -- the tree behaves exactly as it did before the port.
	//
	//go-only: this emitter has no python original; see the file header.
	if len(exact) == 0 || len(normalised) == 0 {
		return oeRefuse("the dump has an empty exact or normalised map. Re-run " +
			"`go run ./scripts/gamedatadump item-mod-stat-order`.")
	}

	type pair struct{ exact, normalised string }
	merged := map[string]*pair{}
	for _, table := range []struct {
		m     map[string]any
		exact bool
	}{{exact, true}, {normalised, false}} {
		for k, v := range table.m {
			f, ok := oeFloat(v)
			//go-only: this emitter has no python original; see the file header.
			if !ok || f <= 0 {
				return oeRefuse(fmt.Sprintf("statOrder for %s is %s; 0 is the absent marker and "+
					"the dumper refuses anything <= 0, so the dump is truncated or hand-edited",
					oeGoStr(k), oeStr(v)))
			}
			p := merged[k]
			if p == nil {
				p = &pair{exact: "0", normalised: "0"}
				merged[k] = p
			}
			if table.exact {
				p.exact = oeGoNum(v)
			} else {
				p.normalised = oeGoNum(v)
			}
		}
	}
	keys := make(map[string]any, len(merged))
	for k := range merged {
		keys[k] = nil
	}

	var b strings.Builder
	fmt.Fprintf(&b, imsoHeader, oeVersion(dump))
	b.WriteString(imsoDecoder)
	b.WriteString("\nvar itemModStatOrderRows = [...]itemModStatOrderRow{\n")
	for _, k := range oeSortedKeys(keys) {
		p := merged[k]
		fmt.Fprintf(&b, "\t{%s, %s, %s},\n", oeGoStr(k), p.exact, p.normalised)
	}
	b.WriteString("}\n")

	if rc := oeWriteGo(argv[1], b.String()); rc != 0 {
		return rc
	}
	fmt.Fprintf(os.Stderr, "wrote %s (%d keys: %d exact, %d normalised)\n",
		argv[1], len(merged), len(exact), len(normalised))
	return 0
}
